(5617562, 814279, 108351, '<td valign="top">I like the perspective, very nice.</td>', 'I like the perspective, very nice.', '2009-08-19 21:22:33.000000', NULL, 1),
(5617564, 813536, 108351, '<td valign="top">The scale looks good. Something odd is going on with the highlight on the orange, and the shadows on the fruit that is a bit distracting.</td>', 'The scale looks good. Something odd is going on with the highlight on the orange, and the shadows on the fruit that is a bit distracting.', '2009-08-19 21:24:02.000000', NULL, 1),
(5617572, 814191, 108351, '<td valign="top">I like the blender and the frogs. The background is a bit distracting.<br/> <br/>My condolences to the third frog that provided that lovely red color.</td>', 'I like the blender and the frogs. The background is a bit distracting. My condolences to the third frog that provided that lovely red color.', '2009-08-19 21:28:29.000000', NULL, 1),
(5617580, 814862, 107410, '<td valign="top">OK, I looked at it again on a different monitor and still feel that you lost too much in the shadows. The concept is great, the picture is very sharp and fills the frame but it just feels like it''s missing something. Overall very good though.</td>', 'OK, I looked at it again on a different monitor and still feel that you lost too much in the shadows. The concept is great, the picture is very sharp and fills the frame but it just feels like it''s missing something. Overall very good though.', '2009-08-19 21:39:13.000000', NULL, 1),
(5617581, 814570, 107410, '<td valign="top">This is a well executed shot: sharp, nice feeling of action, but it just seems to lack "punch." 7</td>', 'This is a well executed shot: sharp, nice feeling of action, but it just seems to lack "punch." 7', '2009-08-19 21:39:29.000000', NULL, 1),
(5617619, 813642, 107410, '<td valign="top">I wish you would''ve AT LEAST taken the stuff off the top!</td>', 'I wish you would''ve AT LEAST taken the stuff off the top!', '2009-08-19 22:09:23.000000', NULL, 1),
(5617622, 813604, 107410, '<td valign="top">+1 simply because you went with something other than a black or white background.</td>', '+1 simply because you went with something other than a black or white background.', '2009-08-19 22:11:38.000000', NULL, 1),
(5617629, 814554, 107410, '<td valign="top">Interesting take on the theme. Kudos for entering a shot sure to get a bunch of DNMC votes. I would be interested to see you do this shot again with a keylight on the bottle.</td>', 'Interesting take on the theme. Kudos for entering a shot sure to get a bunch of DNMC votes. I would be interested to see you do this shot again with a keylight on the bottle.', '2009-08-19 22:16:47.000000', NULL, 1),
